<template>
 <section class="narriva-demo" :class="{'narriva-demo--compact':compact}" aria-label="Narriva interactive walkthrough" data-analytics-area="narriva">
  <header class="nd-header"><div><img :src="NARRIVA_BRAND.logo" alt="Narriva by AuricWell" /><span>Note Workspace</span></div><span>Meadowbrook Therapy <small>Fictional practice</small></span></header>
  <div class="nd-disclosure"><span>INTERACTIVE EXAMPLE</span><p>{{ NARRIVA_DEMO_NOTICE }}</p><button type="button" @click="reset" data-analytics-id="narriva-reset">Reset</button></div>
  <nav class="nd-tour" aria-label="Narriva walkthrough steps"><button v-for="(step,index) in steps" :key="step.id" type="button" :aria-pressed="view===step.id" @click="navigate(step.id)" :data-analytics-id="step.analytics"><span>{{ index+1 }}</span>{{ step.label }}</button></nav>
  <p class="nd-guide" role="status">{{ announcement || guidance }}</p>
  <div class="nd-layout">
   <aside class="nd-drafts" aria-label="Fictional note drafts"><h3>Started drafts <span>3</span></h3><button v-for="(note,index) in narrivaExamples" :key="note.id" type="button" :aria-pressed="selected===index" @click="choose(index)" data-analytics-id="narriva-draft" data-analytics-label="Open a fictional Narriva draft"><strong>{{ note.name }}</strong><span>{{ note.focus }}</span><small>{{ note.date }} · Draft example</small></button><p>Choose another fictional client to explore a different session.</p></aside>
   <div class="nd-main">
    <div class="nd-note-header"><div><p>{{ example.name }} · {{ example.date }}</p><h3>{{ view==='work'?'Supervisor My Work':view==='sign'?'Review before signing':view==='check'?'Narriva Compliance':'Individual therapy progress note' }}</h3><span>90834 · 45 minutes · Telehealth · Client at home</span></div><span class="nd-status">{{ supervisorSigned?'Co-sign simulated':providerSigned?'Provider signature simulated':'Draft example' }}</span></div>
    <template v-if="view==='note'">
     <NarrivaModeChooser v-model="method" :compact="compact" @save-default="announce('Writing preference changed in this example only.')" />
     <div class="nd-source"><h4>{{ method==='manual'?'Clinician-authored note':method==='smart_notes'?'Smart Notes · Guided source':'Session Narrative' }}</h4><p>{{ method==='manual'?'Write and edit your own documentation. Narriva assistance is optional.':method==='smart_notes'?'Guided prompts organize the intervention, client response, progress and next steps.':'A session narrative becomes a structured draft for the clinician to review.' }}</p><details><summary>Review the fictional session source</summary><p>{{ example.source }}</p><p><strong>Fictional source context:</strong> The saved example includes reviewed structured safety fields, applicable encounter consent and a treatment plan linking the session to functional coping goals. The service and 45-minute encounter match. These are supplied sample facts, not findings inferred from this narrative.</p><p class="nd-privacy">In the app, use roles rather than identifying details in the narrative. Session recording is optional and requires applicable signed participant consent and practice activation.</p></details><button v-if="method!=='manual'" type="button" class="nd-secondary" @click="previewDraft" data-analytics-id="narriva-generate">Preview {{ method==='smart_notes'?'Smart Notes':'Narriva' }} draft</button></div>
     <div class="nd-output" data-analytics-area="note-editor"><div class="nd-output-label"><span>{{ method==='manual'?'Clinician-authored example':'Narriva draft · clinician review required' }}</span><button type="button" @click="view='summary'" data-analytics-id="narriva-summary">View summary →</button></div><article v-for="section in sections" :key="section.key"><h4>{{ section.label }}</h4><p>{{ section.text }}</p></article></div>
     <div class="nd-next"><button type="button" class="nd-primary" @click="runChecks" :disabled="busy" data-analytics-id="narriva-check">Run example note check</button><button v-if="passed&&!providerSigned" type="button" class="nd-secondary" @click="beginSignature('provider')">Review and sign (demo)</button><span>Checks support your review; they never sign for you.</span></div>
    </template>
    <template v-else-if="view==='check'">
     <div class="nd-scenarios" role="group" aria-label="Choose an illustrative check outcome"><button type="button" :aria-pressed="scenario==='pass'" @click="changeScenario('pass')" :disabled="busy" data-analytics-id="narriva-pass">Complete note</button><button type="button" :aria-pressed="scenario==='needs-review'" @click="changeScenario('needs-review')" :disabled="busy" data-analytics-id="narriva-fail">{{ scenario==='needs-review'&&corrected?'Missing plan · corrected':'Missing follow-up plan' }}</button></div>
     <p class="nd-explanation">{{ corrected?'This sample includes the specific plan from the session source.':'This sample’s plan only says “Continue therapy.” Run the example check to see the finding, then apply the source-supported correction.' }}</p>
     <button type="button" class="nd-primary nd-run" :disabled="busy" @click="runChecks" data-analytics-id="narriva-check">{{ busy?'Showing the five checks…':'Run example note check' }}</button>
     <NarrivaCompliancePanel :review="review" :busy="busy" @retry="runChecks" @action="applyCorrection" />
     <div v-if="passed" class="nd-next"><button type="button" class="nd-primary" @click="beginSignature('provider')" :disabled="providerSigned" data-analytics-id="narriva-sign-review">{{ providerSigned?'Provider signature simulated':'Review and sign (demo)' }}</button><button type="button" class="nd-secondary" @click="navigate('work')" data-analytics-id="narriva-work">See My Work Quick Sign →</button></div>
    </template>
    <template v-else-if="view==='work'">
     <div class="nd-person"><img src="/assets/schoolcarebridge/demo-tessa.png" alt="Fictional portrait of Dr. Tessa Brooks" loading="lazy" width="46" height="58"/><div><strong>Dr. Tessa Brooks, PhD</strong><span>Clinical supervisor · Notes to co-sign</span></div></div>
     <p class="nd-explanation">A provider-signed note with a current Narriva pass can offer Quick Sign in My Work. It still opens explicit review and attestation. Try Quick look on hover, focus or tap, and open Treatment history.</p>
     <article class="nd-work-card"><header><div><strong>{{ example.name }}</strong><span>Milo Chen, LPCC · {{ example.date }} · 90834</span></div><span>{{ supervisorSigned?'Co-sign simulated':passed&&providerSigned?'Ready for co-sign review':'Review required' }}</span></header><p v-if="!providerSigned">First complete the example note check and simulate the provider’s signature.</p><img v-if="passed&&providerSigned&&!supervisorSigned" class="nd-quick-badge" :src="NARRIVA_BRAND.quickSign" alt="Illustrative Narriva Quick Sign Approved"/><NoteReviewActions :key="`${example.id}:${revision}`" :item="workItem" :load-insights="loadInsights" allow-quick-sign @open-note="view='note'" @quick-sign="beginSignature('supervisor')" /></article>
     <button v-if="!providerSigned" type="button" class="nd-secondary" @click="navigate('check')">Return to note check</button>
     <p v-if="supervisorSigned" class="nd-success" role="status">Supervisor signature simulated. No actual note was co-signed, completed or submitted.</p>
    </template>
    <template v-else-if="view==='summary'"><p class="nd-explanation">The app’s saved-note summary, using fictional narrative and a session artifact.</p><NarrivaNoteSummary :quick-look="insights.quickLook" :source-revision="insights.sourceRevision" @open-note="view='note'"/><button type="button" class="nd-secondary" @click="view='note'">Back to note</button></template>
    <template v-else-if="view==='history'"><p class="nd-explanation">The app’s treatment-history view, with five fictional visits. Clinician objective ratings stay separate from client-reported check-ins.</p><NarrivaTreatmentHistory :history="insights.treatmentHistory"/></template>
    <template v-else-if="view==='sign'">
     <div class="nd-person"><img :src="signer==='supervisor'?'/assets/schoolcarebridge/demo-tessa.png':'/assets/schoolcarebridge/demo-milo.png'" alt="Fictional staff portrait" loading="lazy" width="46" height="58"/><div><strong>{{ signer==='supervisor'?'Dr. Tessa Brooks, PhD':'Milo Chen, LPCC' }}</strong><span>{{ signer==='supervisor'?'Supervisor co-sign review':'Provider signature review' }} · Demonstration only</span></div></div>
     <p class="nd-success">Illustrative checks passed. Review the full note below before simulating a signature.</p><article v-for="section in sections" :key="section.key" class="nd-sign-section"><h4>{{ section.label }}</h4><p>{{ section.text }}</p></article>
     <label class="nd-attest"><input v-model="attested" type="checkbox" data-analytics-id="narriva-attest"/>I reviewed this fictional note. Simulate my {{ signer==='supervisor'?'co-signature':'provider signature' }}.</label>
     <div class="nd-next"><button type="button" class="nd-primary" :disabled="!attested||!passed||busy" @click="finishSignature" data-analytics-id="narriva-sign">{{ signer==='supervisor'?'Simulate Quick Sign':'Simulate provider signature' }}</button><button type="button" class="nd-secondary" @click="view=signer==='supervisor'?'work':'check'">Cancel</button></div><p class="nd-explanation">In the app, signing revalidates access, the exact saved note version, assignments and current Narriva eligibility. This example creates no signature.</p>
    </template>
   </div>
   <aside class="nd-context"><div class="nd-person"><img src="/assets/schoolcarebridge/demo-milo.png" alt="Fictional portrait of Milo Chen" loading="lazy" width="40" height="52"/><div><strong>Milo Chen, LPCC</strong><span>Assigned provider</span></div></div><h3>Treatment context</h3><p>{{ example.focus }}</p><dl><div><dt>Service</dt><dd>Individual psychotherapy</dd></div><div><dt>Frequency</dt><dd>Weekly · Fictional plan</dd></div><div><dt>Plan status</dt><dd>Active example</dd></div></dl><button type="button" @click="view='history'" data-analytics-id="narriva-history">Treatment progress →</button><button type="button" @click="view='summary'" data-analytics-id="narriva-summary">View summary →</button><button type="button" @click="view='work'" data-analytics-id="narriva-work">My Work →</button><small>All identities, scores, notes and results in this walkthrough are fictional.</small></aside>
