 </section>
</template>
<script setup>
import { computed, onBeforeUnmount, ref } from 'vue';
import NarrivaModeChooser from '../../components/clinical/NarrivaModeChooser.vue';
import NarrivaCompliancePanel from '../../components/clinical/NarrivaCompliancePanel.vue';
import NarrivaTreatmentHistory from '../../components/clinical/NarrivaTreatmentHistory.vue';
import NarrivaNoteSummary from '../../components/clinical/NarrivaNoteSummary.vue';
import NoteReviewActions from '../../components/clinical/NoteReviewActions.vue';
import { NARRIVA_BRAND, NARRIVA_CHECKS } from '../../config/narrivaBrand.js';
import { NARRIVA_DEMO_AGENCY, NARRIVA_DEMO_NOTICE, narrivaExamples, exampleSections, exampleNarrivaReview, exampleReviewInsights, exampleTreatmentHistory } from '../demo/narriva.js';
const props=defineProps({compact:Boolean,initialView:{type:String,default:'note'}});
const selected=ref(0),view=ref(props.initialView),method=ref('narriva'),scenario=ref('pass'),corrected=ref(true),review=ref(null),busy=ref(false),providerSigned=ref(false),supervisorSigned=ref(false),signer=ref('provider'),attested=ref(false),announcement=ref(''),revision=ref(0);
const steps=[{id:'note',label:'Write a note',analytics:'narriva-write'},{id:'check',label:'Check the note',analytics:'narriva-check-view'},{id:'work',label:'My Work & Quick Sign',analytics:'narriva-work'},{id:'history',label:'Treatment progress',analytics:'narriva-history'}];
const example=computed(()=>narrivaExamples[selected.value]);
const sections=computed(()=>exampleSections(example.value,corrected.value));
const passed=computed(()=>!busy.value&&review.value?.status==='passed'&&review.value?.quickSignEligible===true);
const insights=computed(()=>exampleReviewInsights(example.value.id,NARRIVA_DEMO_AGENCY,sections.value,exampleTreatmentHistory({example:example.value})));
const workItem=computed(()=>({clinicalNoteId:example.value.id,agencyId:NARRIVA_DEMO_AGENCY,narriva:{quickSignEligible:passed.value&&providerSigned.value&&!supervisorSigned.value},updatedAt:revision.value}));
const guidance=computed(()=>({note:'Explore a fictional draft, then run the example note check.',check:'Choose a complete note or a missing-plan example. Watch all five checks, then review the result.',work:'Quick Sign appears only after the sample passes and its provider signature is simulated.',history:'Review up to five visits, the documented goal and separate client feedback.',summary:'View the saved-note summary and supporting materials.',sign:'Review and attest before a simulated signature.'}[view.value]));
let timer=null,generation=0;
function cancel(){clearTimeout(timer);generation++;busy.value=false;}
function announce(text){announcement.value=text;}
function navigate(target){view.value=target;announcement.value='';attested.value=false;}
function clearState(){cancel();review.value=null;providerSigned.value=false;supervisorSigned.value=false;attested.value=false;announcement.value='';revision.value++;}
function reset(){clearState();selected.value=0;view.value=props.initialView;method.value='narriva';scenario.value='pass';corrected.value=true;}
function choose(index){clearState();selected.value=index;view.value='note';scenario.value='pass';corrected.value=true;}
function changeScenario(value){clearState();scenario.value=value;corrected.value=value==='pass';view.value='check';}
function previewDraft(){announce('The fictional session source is organized into the sample draft below. No generation request was sent.');}
function runChecks(){
 cancel();const current=generation;view.value='check';busy.value=true;attested.value=false;providerSigned.value=false;supervisorSigned.value=false;revision.value++;
 review.value={id:'fictional-running',exampleOnly:true,status:'running',checks:NARRIVA_CHECKS.map(check=>({...check,status:'pending'}))};
 const final=exampleNarrivaReview({passed:corrected.value});final.scoring.criteria[0].evidence=[sections.value.find(section=>section.key==='interventions').text];let index=0;
 function next(){if(current!==generation)return;if(index===NARRIVA_CHECKS.length){review.value=final;busy.value=false;announce(corrected.value?'Example complete: all five checks pass. Review the note before simulating a signature.':'Example complete: review required. Apply the correction supported by the session source, then run the example again.');return;}review.value={...review.value,checks:review.value.checks.map((check,i)=>({...check,status:i<index?final.checks[i].status:i===index?'running':'pending'}))};announce(`Simulating check ${index+1} of 5: ${NARRIVA_CHECKS[index].label}.`);index++;timer=setTimeout(next,320);}
 next();
}
function applyCorrection(){if(busy.value)return;corrected.value=true;review.value=exampleNarrivaReview({passed:false,stale:true});attested.value=false;providerSigned.value=false;supervisorSigned.value=false;revision.value++;announce('Sample plan updated from the existing session source. The prior result is stale; run the example check again.');}
function beginSignature(kind){if(!passed.value||kind==='supervisor'&&!providerSigned.value)return;signer.value=kind;attested.value=false;view.value='sign';announcement.value='';}
function finishSignature(){if(!attested.value||!passed.value||busy.value||signer.value==='supervisor'&&!providerSigned.value)return;if(signer.value==='supervisor')supervisorSigned.value=true;else providerSigned.value=true;attested.value=false;view.value='work';revision.value++;announce(signer.value==='supervisor'?'Quick Sign simulated. No actual note was co-signed, completed or submitted.':'Provider signature simulated. The sample is now in the supervisor’s My Work; explore Quick Sign.');}
async function loadInsights({noteId,agencyId}){if(noteId!==example.value.id||agencyId!==NARRIVA_DEMO_AGENCY)throw Error('Outside fictional example');return {insights:structuredClone(insights.value)};}
onBeforeUnmount(cancel);
</script>
